const money = (n:number|null) => n===null?"COMING SOON":`$${n.toFixed(2)}`;

export default function Home() {
  const [cart,setCart] = useState<Cart>({});
  const [ageConfirmed,setAgeConfirmed] = useState<boolean|null>(null);
  const [drawer,setDrawer] = useState(false);
  const [menu,setMenu] = useState(false);
  const [category,setCategory] = useState("Lighter Sleeves");
  const [query,setQuery] = useState("");
  const [notice,setNotice] = useState("");
  const [selectedProduct,setSelectedProduct] = useState<Product|null>(null);
  const [selectedImage,setSelectedImage] = useState(0);
  const [selectedColor,setSelectedColor] = useState(colorOptions[0]);
  const [detailQty,setDetailQty] = useState(1);
  const [cartColors,setCartColors] = useState<Record<number,string>>({});
  useEffect(()=>{
    try {
      setAgeConfirmed(localStorage.getItem("smokhive-age-confirmed")==="yes");
    } catch {
      setAgeConfirmed(false);
    }
  },[]);
  useEffect(()=>{
    document.body.style.overflow=ageConfirmed===true?"":"hidden";
    return ()=>{document.body.style.overflow=""};
  },[ageConfirmed]);
  useEffect(()=>{ try { setCart(JSON.parse(localStorage.getItem("smokhive-cart")||"{}")); } catch {} },[]);
  useEffect(()=>{ localStorage.setItem("smokhive-cart",JSON.stringify(cart)); },[cart]);
  useEffect(()=>{ try { setCartColors(JSON.parse(localStorage.getItem("smokhive-colors")||"{}")); } catch {} },[]);
  useEffect(()=>{ localStorage.setItem("smokhive-colors",JSON.stringify(cartColors)); },[cartColors]);
  useEffect(()=>{
    if(!selectedProduct) return;
    const close=(event:KeyboardEvent)=>{if(event.key==="Escape") setSelectedProduct(null)};
    document.addEventListener("keydown",close);
    document.body.classList.add("modal-open");
    return ()=>{document.removeEventListener("keydown",close);document.body.classList.remove("modal-open")};
  },[selectedProduct]);
  const count = Object.values(cart).reduce((a,b)=>a+b,0);
  const subtotal = products.reduce((s,p)=>s+(cart[p.id]||0)*(p.price??0),0);
  const freeShippingTarget = 50;
  const freeShippingRemaining = Math.max(0,freeShippingTarget-subtotal);
  const freeShippingProgress = Math.min(100,(subtotal/freeShippingTarget)*100);
  const filtered = useMemo(()=>products.filter(p=>p.category===category&&p.name.toLowerCase().includes(query.toLowerCase())),[category,query]);
  const add=(id:number)=>{setCart(c=>({...c,[id]:(c[id]||0)+1}));setNotice("Added to cart");setTimeout(()=>setNotice(""),1400)};
  const viewProduct=(product:Product)=>{setSelectedProduct(product);setSelectedImage(0);setSelectedColor(colorOptions.find(c=>c.className===product.color)||colorOptions[0]);setDetailQty(1)};
  const addConfigured=()=>{if(!selectedProduct||selectedProduct.price===null)return;setCart(c=>({...c,[selectedProduct.id]:(c[selectedProduct.id]||0)+detailQty}));setCartColors(c=>({...c,[selectedProduct.id]:selectedProduct.finish||selectedColor.name}));setSelectedProduct(null);setNotice(`${detailQty} × ${selectedProduct.name} added`);setDrawer(true);setTimeout(()=>setNotice(""),1400)};
  const qty=(id:number,n:number)=>setCart(c=>{const next={...c}; if(n<=0) delete next[id]; else next[id]=n; return next});
  const confirmAge=()=>{
    setAgeConfirmed(true);
    try { localStorage.setItem("smokhive-age-confirmed","yes"); } catch {}
  };
  return <main id="top">
    {ageConfirmed!==true && <div className="age-gate" role="dialog" aria-modal="true" aria-labelledby="age-title" aria-describedby="age-description">
      <div className="age-gate-card">
        <span className="age-mark" aria-hidden="true">18+</span>
        <p className="age-kicker">AGE CHECK</p>
        <h1 id="age-title">ARE YOU 18 OR OLDER?</h1>
        <p id="age-description">You must be 18 or older to enter SmokHive.</p>
        <div className="age-actions">
          <button type="button" className="age-enter" onClick={confirmAge}>YES, I&apos;M 18+</button>
          <a className="age-leave" href="https://www.google.com">NO, LEAVE SITE</a>
        </div>
        <small>By entering, you confirm that you meet the minimum legal age required in your location.</small>
      </div>
    </div>}
    <div className="announcement-bar" aria-label="Store benefits"><span>FREE SHIPPING $50+</span><span>PRINTED TO ORDER</span><span>DURABLE PLA+</span></div>
    <header>
      <a className="logo" href="#top">SMOK<span>HIVE</span></a>
      <nav className={menu?"open":""}><a href="#shop" onClick={()=>setMenu(false)}>Shop</a><a href="#story" onClick={()=>setMenu(false)}>Our process</a><a href="#reviews" onClick={()=>setMenu(false)}>Reviews</a><a href="#faq" onClick={()=>setMenu(false)}>FAQ</a></nav>
      <div className="header-actions"><button className="icon-btn" aria-label="Search" onClick={()=>document.getElementById("search")?.focus()}>⌕</button><button className="cart-btn" onClick={()=>setDrawer(true)} aria-label={`Cart with ${count} items`}>BAG <b>{count}</b></button><button className="menu-btn" onClick={()=>setMenu(!menu)} aria-label="Toggle menu">{menu?"×":"☰"}</button></div>
    </header>

    <section className="hero" id="top">
      <div className="spray spray-one">✦</div><div className="spray spray-two">////</div>
      <div className="hero-copy"><p className="eyebrow">MAKE SPACE. KEEP STYLE.</p><h1>ORGANIZE<br/><i>OUT</i> LOUD.</h1><p className="dek">3D-printed organizers made for desks that refuse to blend in. Designed in small batches. Built for daily use.</p><div className="hero-actions"><a className="primary" href="#shop">SHOP THE DROP →</a><button className="text-btn" onClick={()=>add(25)}>ADD THE FULL KIT</button></div><div className="rating">★★★★★ <span>4.9 · 2,400+ organized spaces</span></div></div>
      <div className="hero-art"><img src="data:image/webp;base64," alt="Blue and grey 3D-printed desk organizers on concrete plinths"/><div className="price-tag"><span>GALLERY DESK KIT<br/><small>6 PIECES</small></span><b>$74</b></div></div>
    </section>
    <section className="product-ticker" aria-label="Shop categories">
      <div className="product-ticker-track">
        {[false,true].map(duplicate=><div className="product-ticker-group" aria-hidden={duplicate||undefined} key={duplicate?"duplicate":"primary"}>
          {shopCategories.map(categoryName=><span className="product-ticker-item" key={categoryName}>
            <a href="#shop" tabIndex={duplicate?-1:undefined} onClick={()=>setCategory(categoryName)}><small>SHOP CATEGORY</small>{categoryName.toUpperCase()}<b>EXPLORE →</b></a><i aria-hidden="true">✦</i>
          </span>)}
        </div>)}
      </div>
    </section>

    <section className="shop" id="shop"><div className="section-head"><div><p className="kicker">THE DAILY EDIT.</p><h2>FUNCTION, WITH A LOUDER VOICE.</h2></div><p>Small-batch pieces that bring order without draining the personality from your space.</p></div>
      <div className="tools"><div className="filters">{shopCategories.map(c=><button key={c} className={category===c?"active":""} aria-pressed={category===c} onClick={()=>setCategory(c)}>{c}</button>)}</div><input id="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="SEARCH PIECES" aria-label="Search products"/></div>
      <div className="grid">{filtered.map(p=><article className="product" key={p.id} onClick={()=>viewProduct(p)} onKeyDown={e=>{if(e.key==="Enter"||e.key===" ")viewProduct(p)}} tabIndex={0} role="button" aria-label={`View details for ${p.name}`}><div className={`product-art ${p.color}${p.images?" has-photo":""}${p.imageFit==="contain"?" photo-contain":""}${p.imageFit==="cover"?" photo-cover":""}${p.imageBackground==="light"?" photo-light":""}`}>{p.images?<img className="product-photo" src={p.images[0]} alt={p.imageAlt||p.name} loading="lazy"/>:<div className="shape"><span></span><span></span><span></span></div>}</div><div className="product-copy"><div><p>{p.category}</p><h3>{p.name}</h3></div><b>{money(p.price)}</b></div></article>)}</div>
      {!filtered.length&&<p className="empty">No pieces found. Try another search.</p>}
    </section>

    <section className="story" id="story"><div className="story-poster"><span>NO.</span><strong>MASS<br/>BORING.</strong><i>JUST GOOD DESIGN.</i></div><div><p className="eyebrow pink-label">PRINTED WITH PURPOSE</p><h2>ONE LAYER<br/>AT A TIME.</h2><p>Every SmokHive piece is printed to order in durable plant-based PLA+. That means less waste, small-batch quality control, and a finish with real texture.</p><ul><li><b>01</b> Designed for real routines</li><li><b>02</b> Printed in small batches</li><li><b>03</b> Packed without plastic fluff</li></ul></div></section>
    <section className="reviews" id="reviews"><p className="kicker">HEARD ON THE STREET.</p><div className="review-grid"><blockquote>“The grip sleeve fits perfectly and feels like a tiny art object.”<cite>— Maya R. ★★★★★</cite></blockquote><blockquote>“Feels sturdy, fits perfectly, and the pink is even better in person.”<cite>— Jordan K. ★★★★★</cite></blockquote><blockquote>“Finally, small-batch storage that doesn’t look like office supply storage.”<cite>— Alex T. ★★★★★</cite></blockquote></div></section>
    <section className="faq" id="faq"><h2>THE FINE PRINT.</h2>{[["How long does printing take?","Most pieces are made and dispatched within 2–4 business days."],["What material do you use?","Durable PLA+, a plant-based plastic chosen for crisp detail and everyday strength."],["Can I return an item?","Yes. Unused items can be returned within 30 days of delivery."],["Will colors match exactly?","Small shade variations can happen between material batches—part of small-batch production."]].map(([q,a])=><details key={q}><summary>{q}<span>+</span></summary><p>{a}</p></details>)}</section>
    <section className="contact-section" id="contact" aria-labelledby="contact-title">
      <div className="contact-stamp" aria-hidden="true">GET IN TOUCH</div>
      <div className="contact-copy">
        <p>NEED A HAND?</p>
        <h2 id="contact-title">LET’S SORT IT.</h2>
        <span>Questions about an order, a color, or the right piece for your space? Send the studio a note.</span>
      </div>
      <div className="contact-actions">
        <a className="contact-primary" href="mailto:hello@smokhive.com">EMAIL THE STUDIO →</a>
        <a className="contact-secondary" href="#faq">CHECK THE FAQ ↗</a>
        <small>USUALLY REPLIES IN 1–2 BUSINESS DAYS</small>
      </div>
    </section>
    <footer className="site-footer">
      <div className="footer-top">
        <div className="footer-brand">
          <div className="logo">SMOKHIVE</div>
          <h2>MAKE SPACE.<br/>KEEP STYLE.</h2>
          <p>Small-batch 3D-printed organizers built to bring order, color and personality to everyday spaces.</p>
        </div>
        <div className="footer-links" aria-label="Footer navigation">
          <div><h3>SHOP</h3><a href="#shop">Lighter Sleeves</a><a href="#shop">Containers</a><a href="#shop">Rolling Kits</a><a href="#shop">Trays</a><a href="#shop">Figurines</a><a href="#shop">Stand</a></div>
          <div><h3>INFO</h3><a href="#story">Our process</a><a href="#reviews">Reviews</a><a href="#faq">Shipping &amp; FAQ</a><a href="#contact">Contact</a></div>
        </div>
        <div className="footer-signup">
          <span>DROP ALERTS</span>
          <h3>GET THE NEXT EDIT FIRST.</h3>
          <p>New colors, limited runs and studio updates—sent occasionally.</p>
          <form onSubmit={e=>{e.preventDefault();e.currentTarget.reset();alert("You're on the list.")}}>
            <label className="sr-only" htmlFor="footer-email">Email address</label>
            <input id="footer-email" type="email" placeholder="EMAIL ADDRESS" required/>
            <button type="submit" aria-label="Join the SmokHive mailing list">JOIN →</button>
          </form>
        </div>
      </div>
      <div className="footer-bottom">
        <small>© 2026 SMOKHIVE. ALL RIGHTS RESERVED.</small>
        <div><a href="#faq">PRIVACY</a><a href="#faq">TERMS</a><a href="#faq">ACCESSIBILITY</a></div>
        <a className="back-top" href="#top">BACK TO TOP ↑</a>
      </div>
    </footer>

    <div className={drawer?"overlay show":"overlay"} onClick={()=>setDrawer(false)}></div>
    <aside className={drawer?"cart open":"cart"} aria-hidden={!drawer}><div className="cart-head"><div><p>YOUR BAG</p><h2>{count} {count===1?"PIECE":"PIECES"}</h2></div><button onClick={()=>setDrawer(false)} aria-label="Close cart">×</button></div>
      <div className="cart-items">{count===0?<div className="cart-empty"><span>□</span><h3>Your bag is empty.</h3><p>Start with a piece that makes space.</p><button onClick={()=>{setDrawer(false);location.hash="shop"}}>SHOP THE DROP</button></div>:products.filter(p=>cart[p.id]).map(p=><div className="cart-line" key={p.id}>{p.images?<img className="cart-thumb" src={p.images[0]} alt=""/>:<div className={`mini ${colorOptions.find(c=>c.name===cartColors[p.id])?.className||p.color}`}></div>}<div><h3>{p.name}</h3><p>{cartColors[p.id]||p.finish||"Standard color"} · {money(p.price)}</p><div className="quantity"><button onClick={()=>qty(p.id,cart[p.id]-1)}>−</button><span>{cart[p.id]}</span><button onClick={()=>qty(p.id,cart[p.id]+1)}>+</button></div></div><button className="remove" onClick={()=>qty(p.id,0)}>×</button></div>)}</div>
      {count>0&&<div className="cart-foot"><div className="subtotal-row"><span>SUBTOTAL</span><b>{money(subtotal)}</b></div><div className={freeShippingRemaining===0?"shipping-counter unlocked":"shipping-counter"} aria-live="polite"><div className="shipping-counter-copy"><span>{freeShippingRemaining===0?"FREE DELIVERY UNLOCKED":"FREE DELIVERY COUNTER"}</span><b>{freeShippingRemaining===0?"✓":money(freeShippingRemaining)}</b></div><div className="shipping-track" role="progressbar" aria-label="Free delivery progress" aria-valuemin={0} aria-valuemax={freeShippingTarget} aria-valuenow={Math.min(subtotal,freeShippingTarget)}><span style={{width:`${freeShippingProgress}%`}}></span></div><p>{freeShippingRemaining===0?"Your order now qualifies for free delivery.":`Add ${money(freeShippingRemaining)} more to reach free delivery.`}</p></div><button onClick={()=>alert("Demo checkout ready to connect to your payment provider.")}>CHECKOUT →</button><small>Taxes calculated at checkout.</small></div>}
    </aside>
    {selectedProduct&&<div className="detail-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setSelectedProduct(null)}}>
      <section className="detail-modal" role="dialog" aria-modal="true" aria-labelledby="detail-title">
        <button className="detail-close" onClick={()=>setSelectedProduct(null)} aria-label="Close product details">×</button>
        <div className={`detail-art studio-media ${selectedProduct.images?"has-photo":selectedColor.className}${selectedProduct.imageBackground==="light"?" photo-light":""}`}>
          <span className="detail-sticker">MADE TO ORDER</span>
          {selectedProduct.images?<>
            <img className="detail-photo" src={selectedProduct.images[selectedImage]} alt={`${selectedProduct.imageAlt||selectedProduct.name}, view ${selectedImage+1} of ${selectedProduct.images.length}`}/>
            <div className="detail-thumbs" aria-label="Product image gallery">{selectedProduct.images.map((image,index)=><button key={image} className={selectedImage===index?"active":""} onClick={()=>setSelectedImage(index)} aria-label={`Show product image ${index+1}`} aria-pressed={selectedImage===index}><img src={image} alt=""/></button>)}</div>
          </>:<div className="detail-shape"><span></span><span></span><span></span></div>}
          <small>{selectedProduct.images?`${selectedProduct.images.length} PRODUCT VIEWS`:"VISIBLE LAYER TEXTURE · PLA+"}</small>
        </div>
        <div className="detail-info">
          <p className="detail-category">{selectedProduct.category} / SMALL BATCH</p>
          <h2 id="detail-title">{selectedProduct.name}</h2>
          <div className="detail-price"><strong>{money(selectedProduct.price)}</strong><span>★★★★★ 4.9</span></div>
          <p>{selectedProduct.desc} Printed to order with durable PLA+ and finished with the distinctive layer texture that makes every piece feel designed, not mass-produced.</p>
          <div className="detail-points"><span>✓ Durable PLA+</span><span>✓ Ships in 2–4 days</span><span>✓ 30-day returns</span></div>
          {selectedProduct.finish?<div className="product-finish"><span>FINISH</span><b>{selectedProduct.finish}</b></div>:<fieldset><legend>COLOR — <b>{selectedColor.name}</b></legend><div className="swatches">{colorOptions.map(color=><button key={color.name} className={selectedColor.name===color.name?"selected":""} style={{background:color.value}} onClick={()=>setSelectedColor(color)} aria-label={`Choose ${color.name}`} aria-pressed={selectedColor.name===color.name}></button>)}</div></fieldset>}
          <div className="detail-buy">{selectedProduct.price===null?<button className="detail-add" disabled>COMING SOON</button>:<><div className="detail-qty"><button onClick={()=>setDetailQty(q=>Math.max(1,q-1))} aria-label="Decrease quantity">−</button><span>{detailQty}</span><button onClick={()=>setDetailQty(q=>q+1)} aria-label="Increase quantity">+</button></div><button className="detail-add" onClick={addConfigured}>ADD TO BAG · {money(selectedProduct.price*detailQty)} →</button></>}</div>
          <small className="detail-note">Free shipping on orders over $50.</small>
        </div>
      </section>
    </div>}
    {notice&&<div className="toast">✓ {notice}</div>}
  </main>
}
